import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { registerDeviceHandler } from "../handlers/registerDeviceHandler";
import type { ApiError } from "../runtime/client";
import type { RegisterDeviceRequest } from "../types/RegisterDeviceRequest";

type Data = Awaited<ReturnType<typeof registerDeviceHandler>>;
type Vars = RegisterDeviceRequest;

export function useRegisterDevice(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => registerDeviceHandler(vars),
    ...options,
  });
}
